-- Ciclo completo de solicitud, reclutamiento, evaluacion, seleccion y nombramiento.
alter table public.hr_recruitment_processes add column if not exists request_date date not null default current_date;
alter table public.hr_recruitment_processes add column if not exists requested_by_name text not null default '';
alter table public.hr_recruitment_processes add column if not exists justification text not null default '';
alter table public.hr_recruitment_processes add column if not exists request_status text not null default 'PENDIENTE' check(request_status in('PENDIENTE','APROBADA','RECHAZADA'));
alter table public.hr_recruitment_processes add column if not exists approved_by uuid references public.app_users(id);
alter table public.hr_recruitment_processes add column if not exists approved_at timestamptz;
alter table public.hr_recruitment_processes add column if not exists approval_observation text not null default '';

create table if not exists public.hr_recruitment_candidates(
 id uuid primary key default gen_random_uuid(),process_id uuid not null references public.hr_recruitment_processes(id) on delete cascade,
 document_number text not null,full_name text not null,phone text not null default '',email text not null default '',academic_level text not null default '',
 current_status text not null default 'REGISTRADO' check(current_status in('REGISTRADO','PRESELECCIONADO','ENTREVISTA','EVALUADO','SELECCIONADO','DESCARTADO','NOMBRADO')),
 application_date date not null default current_date,notes text not null default '',employee_id uuid references public.hr_employees(id),
 created_by uuid not null references public.app_users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(process_id,document_number)
);
create table if not exists public.hr_candidate_evaluations(
 id uuid primary key default gen_random_uuid(),candidate_id uuid not null references public.hr_recruitment_candidates(id) on delete cascade,
 evaluation_type text not null check(evaluation_type in('ENTREVISTA','PRUEBA_TECNICA','PSICOMETRICA','REFERENCIAS','OTRA')),
 evaluation_date date not null default current_date,score numeric(5,2) check(score between 0 and 100),result text not null default '',observation text not null default '',
 evaluator_id uuid not null references public.app_users(id),created_at timestamptz not null default now()
);
create table if not exists public.hr_candidate_documents(
 id uuid primary key default gen_random_uuid(),candidate_id uuid not null references public.hr_recruitment_candidates(id) on delete cascade,
 document_type text not null,document_name text not null,document_url text not null,uploaded_by uuid not null references public.app_users(id),created_at timestamptz not null default now()
);
create index if not exists hr_candidates_process_idx on public.hr_recruitment_candidates(process_id,current_status);
create index if not exists hr_candidate_evaluations_idx on public.hr_candidate_evaluations(candidate_id,evaluation_date desc);
alter table public.hr_recruitment_candidates enable row level security;alter table public.hr_candidate_evaluations enable row level security;alter table public.hr_candidate_documents enable row level security;
revoke all on public.hr_recruitment_candidates,public.hr_candidate_evaluations,public.hr_candidate_documents from anon,authenticated;

create or replace function public.list_hr_recruitment(p_token text)
returns jsonb language plpgsql security definer set search_path=public,extensions as $$declare v_user public.app_users;begin v_user:=public.hr_authenticated_user(p_token);
 if v_user.id is null or (v_user.role<>'Administrador' and not coalesce((v_user.permissions->>'ver_recursos_humanos')::boolean,false)) then return jsonb_build_object('success',false,'error','No posee permiso para consultar reclutamiento.');end if;
 return jsonb_build_object('success',true,
 'processes',coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc) from(select r.*,v.position_name,v.direction_name,v.department_name,v.division_name,v.section_name,v.center_name,v.monthly_amount,v.execution_fund,v.program,v.subproduct,v.activity,(select count(*) from public.hr_recruitment_candidates c where c.process_id=r.id) candidate_count from public.hr_recruitment_processes r join public.hr_vacancies v on v.id=r.vacancy_id)x),'[]'::jsonb),
 'candidates',coalesce((select jsonb_agg(to_jsonb(x) order by x.application_date desc,x.full_name) from(select c.*,(select coalesce(round(avg(e.score),2),0) from public.hr_candidate_evaluations e where e.candidate_id=c.id) average_score,coalesce((select jsonb_agg(to_jsonb(e) order by e.evaluation_date desc) from public.hr_candidate_evaluations e where e.candidate_id=c.id),'[]'::jsonb) evaluations,coalesce((select jsonb_agg(to_jsonb(d) order by d.created_at desc) from public.hr_candidate_documents d where d.candidate_id=c.id),'[]'::jsonb) documents from public.hr_recruitment_candidates c)x),'[]'::jsonb));end $$;

create or replace function public.manage_hr_recruitment(p_token text,p_action text,p_data jsonb)
returns jsonb language plpgsql security definer set search_path=public,extensions as $$declare v_user public.app_users;v_process public.hr_recruitment_processes;v_candidate public.hr_recruitment_candidates;v_vacancy public.hr_vacancies;v_id uuid;v_employee uuid;v_unit uuid;v_code text;v_doc text;begin v_user:=public.hr_authenticated_user(p_token);
 if v_user.id is null or (v_user.role<>'Administrador' and not coalesce((v_user.permissions->>'editar_recursos_humanos')::boolean,false)) then return jsonb_build_object('success',false,'error','No posee permiso para gestionar reclutamiento.');end if;
 if p_action='SOLICITAR' then select * into v_vacancy from public.hr_vacancies where id=(p_data->>'vacancy_id')::uuid and status in('VACANTE','CON_RECLUTAMIENTO') for update;if v_vacancy.id is null or v_vacancy.decision<>'CUBRIR' then return jsonb_build_object('success',false,'error','La vacante debe estar disponible y marcada para cubrir.');end if;
  insert into public.hr_recruitment_processes(vacancy_id,reference,notes,requested_by_name,justification,created_by) values(v_vacancy.id,trim(coalesce(p_data->>'reference','')),trim(coalesce(p_data->>'notes','')),trim(coalesce(p_data->>'requested_by_name',v_user.full_name)),trim(coalesce(p_data->>'justification','')),v_user.id) on conflict(vacancy_id) where status not in('CERRADO','CANCELADO') do update set reference=excluded.reference,notes=excluded.notes,requested_by_name=excluded.requested_by_name,justification=excluded.justification,updated_at=now() returning id into v_id;update public.hr_vacancies set status='CON_RECLUTAMIENTO',updated_at=now() where id=v_vacancy.id;
 elsif p_action in('APROBAR','RECHAZAR') then select * into v_process from public.hr_recruitment_processes where id=(p_data->>'process_id')::uuid for update;if v_process.id is null then return jsonb_build_object('success',false,'error','Proceso no encontrado.');end if;if v_user.role<>'Administrador' and not coalesce((v_user.permissions->>'aprobar_recursos_humanos')::boolean,false) then return jsonb_build_object('success',false,'error','No posee permiso para aprobar solicitudes.');end if;update public.hr_recruitment_processes set request_status=case when p_action='APROBAR' then 'APROBADA' else 'RECHAZADA' end,status=case when p_action='APROBAR' then 'PUBLICADO' else 'CANCELADO' end,approved_by=v_user.id,approved_at=now(),approval_observation=trim(coalesce(p_data->>'observation','')),updated_at=now() where id=v_process.id;update public.hr_vacancies set status=case when p_action='APROBAR' then 'CON_RECLUTAMIENTO' else 'VACANTE' end,updated_at=now() where id=v_process.vacancy_id;
 elsif p_action='CANDIDATO' then select * into v_process from public.hr_recruitment_processes where id=(p_data->>'process_id')::uuid and request_status='APROBADA' and status not in('CERRADO','CANCELADO');if v_process.id is null then return jsonb_build_object('success',false,'error','La solicitud debe estar aprobada antes de registrar candidatos.');end if;v_doc:=regexp_replace(coalesce(p_data->>'document_number',''),'\D','','g');if length(v_doc)<9 then return jsonb_build_object('success',false,'error','La cédula del candidato no es válida.');end if;insert into public.hr_recruitment_candidates(process_id,document_number,full_name,phone,email,academic_level,notes,created_by) values(v_process.id,v_doc,trim(p_data->>'full_name'),trim(coalesce(p_data->>'phone','')),trim(coalesce(p_data->>'email','')),trim(coalesce(p_data->>'academic_level','')),trim(coalesce(p_data->>'notes','')),v_user.id) on conflict(process_id,document_number) do update set full_name=excluded.full_name,phone=excluded.phone,email=excluded.email,academic_level=excluded.academic_level,notes=excluded.notes,updated_at=now() returning id into v_id;
 elsif p_action='EVALUAR' then select * into v_candidate from public.hr_recruitment_candidates where id=(p_data->>'candidate_id')::uuid for update;if v_candidate.id is null then return jsonb_build_object('success',false,'error','Candidato no encontrado.');end if;insert into public.hr_candidate_evaluations(candidate_id,evaluation_type,evaluation_date,score,result,observation,evaluator_id) values(v_candidate.id,upper(p_data->>'evaluation_type'),coalesce(nullif(p_data->>'evaluation_date','')::date,current_date),coalesce((p_data->>'score')::numeric,0),trim(coalesce(p_data->>'result','')),trim(coalesce(p_data->>'observation','')),v_user.id);update public.hr_recruitment_candidates set current_status=case when upper(p_data->>'evaluation_type')='ENTREVISTA' then 'ENTREVISTA' else 'EVALUADO' end,updated_at=now() where id=v_candidate.id;update public.hr_recruitment_processes set status='EVALUACION',updated_at=now() where id=v_candidate.process_id;
 elsif p_action='DOCUMENTO' then select * into v_candidate from public.hr_recruitment_candidates where id=(p_data->>'candidate_id')::uuid;if v_candidate.id is null then return jsonb_build_object('success',false,'error','Candidato no encontrado.');end if;insert into public.hr_candidate_documents(candidate_id,document_type,document_name,document_url,uploaded_by) values(v_candidate.id,trim(p_data->>'document_type'),trim(p_data->>'document_name'),trim(p_data->>'document_url'),v_user.id) returning id into v_id;
 elsif p_action='SELECCIONAR' then select * into v_candidate from public.hr_recruitment_candidates where id=(p_data->>'candidate_id')::uuid for update;select * into v_process from public.hr_recruitment_processes where id=v_candidate.process_id for update;if v_candidate.id is null or v_process.request_status<>'APROBADA' then return jsonb_build_object('success',false,'error','Candidato o proceso inválido.');end if;update public.hr_recruitment_candidates set current_status=case when id=v_candidate.id then 'SELECCIONADO' else 'DESCARTADO' end,updated_at=now() where process_id=v_process.id and current_status<>'NOMBRADO';update public.hr_recruitment_processes set status='SELECCIONADO',updated_at=now() where id=v_process.id;
 elsif p_action='NOMBRAR' then select * into v_candidate from public.hr_recruitment_candidates where id=(p_data->>'candidate_id')::uuid and current_status='SELECCIONADO' for update;select * into v_process from public.hr_recruitment_processes where id=v_candidate.process_id for update;select * into v_vacancy from public.hr_vacancies where id=v_process.vacancy_id for update;if v_candidate.id is null or v_vacancy.status<>'CON_RECLUTAMIENTO' then return jsonb_build_object('success',false,'error','El candidato no está seleccionado o la plaza ya no está disponible.');end if;if exists(select 1 from public.hr_employees where document_number=v_candidate.document_number) then return jsonb_build_object('success',false,'error','Ya existe un empleado con esta cédula.');end if;
  select id into v_unit from public.organization_units where active and unit_name=coalesce(nullif(v_vacancy.section_name,''),nullif(v_vacancy.division_name,''),nullif(v_vacancy.department_name,''),v_vacancy.direction_name) limit 1;if v_unit is null then return jsonb_build_object('success',false,'error','No se encontró la unidad organizacional de la vacante.');end if;v_code:='EMP-'||lpad(nextval('public.hr_employee_code_seq')::text,6,'0');insert into public.hr_employees(employee_code,document_number,full_name,organization_unit_id,position_name,employment_status,hire_date,created_by,phone,cell_phone,academic_level,payroll_status,direction_name,department_name,division_name,section_name,center_name,execution_fund,program,subproduct,activity,monthly_salary) values(v_code,v_candidate.document_number,v_candidate.full_name,v_unit,v_vacancy.position_name,'Activo',coalesce(nullif(p_data->>'hire_date','')::date,current_date),v_user.id,v_candidate.phone,v_candidate.phone,v_candidate.academic_level,'Activo',v_vacancy.direction_name,v_vacancy.department_name,v_vacancy.division_name,v_vacancy.section_name,v_vacancy.center_name,v_vacancy.execution_fund,v_vacancy.program,v_vacancy.subproduct,v_vacancy.activity,v_vacancy.monthly_amount) returning id into v_employee;
  update public.hr_recruitment_candidates set current_status='NOMBRADO',employee_id=v_employee,updated_at=now() where id=v_candidate.id;update public.hr_recruitment_processes set status='CERRADO',selected_employee_id=v_employee,updated_at=now() where id=v_process.id;update public.hr_vacancies set status='OCUPADA',filled_by_employee_id=v_employee,filled_at=now(),updated_at=now() where id=v_vacancy.id;v_id:=v_employee;
 else return jsonb_build_object('success',false,'error','Acción de reclutamiento inválida.');end if;
 insert into public.security_audit_log(actor_user_id,action,module,detail) values(v_user.id,'RECLUTAMIENTO_'||p_action,'Recursos Humanos',p_data||jsonb_build_object('result_id',v_id));return jsonb_build_object('success',true,'id',v_id,'employee_id',v_employee);end $$;
grant execute on function public.list_hr_recruitment(text),public.manage_hr_recruitment(text,text,jsonb) to anon,authenticated;
